response:
[
  {
    "id": 1,
    "source": "Por mucho dinero que tenga, por mucha propiedad, por mucho derecho a la propiedad privada, está por encima el derecho",
    "text": "هر چقدر هم پول داشته باشد، هر چقدر هم ملک داشته باشد، هر چقدر هم حق مالکیت خصوصی داشته باشد، حق"
  },
  {
    "id": 2,
    "source": "a la gente a poder vivir bajo un techo.",
    "text": "مردم برای داشتن سرپناه بالاتر است"
  },
  {
    "id": 3,
    "source": "Kurz bevor sie starb, sollte Marie Carmen nach Hause zurück dürfen.",
    "text": "کمی پیش از مرگش، قرار بود ماری کارمن اجازه بازگشت به خانه را داشته باشد"
  },
  {
    "id": 4,
    "source": "Aber die Demos gehen weiter.",
    "text": "اما تظاهرات همچنان ادامه دارد"
  },
  {
    "id": 5,
    "source": "Für November ist ein historischer Generalstreik angekündigt.",
    "text": "یک اعتصاب عمومی تاریخی برای ماه نوامبر اعلام شده است"
  },
  {
    "id": 6,
    "source": "Denn für die Protestierenden ist das, was der Rentnerin widerfahren ist, Ausdruck einer Krise,",
    "text": "زیرا برای معترضان، آنچه بر سر این زن بازنشسته آمد، نشان‌دهنده بحرانی است"
  },
  {
    "id": 7,
    "source": "die Spanien schon seit Jahren zu schaffen macht.",
    "text": "که اسپانیا سال‌هاست با آن دست‌وپنج نرم می‌کند"
  },
  {
    "id": 8,
    "source": "Viele Gehälter können nicht mit den Mieten mithalten.",
    "text": "بسیاری از حقوق‌ها با اجاره‌بها همخوانی ندارند"
  },
  {
    "id": 9,
    "source": "Eine Wohnung zu finden ist schwer und eine zu kaufen praktisch unmöglich.",
    "text": "پیدا کردن خانه دشوار و خرید آن عملاً غیرممکن است"
  },
  {
    "id": 10,
    "source": "Angesichts der Demos kündigte Spaniens linke Regierung verschiedene Maßnahmen an.",
    "text": "در پی این تظاهرات، دولت چپ‌گرای اسپانیا اقدامات مختلفی را اعلام کرد"
  },
  {
    "id": 11,
    "source": "Zwangsräumungen von sozial Benachteiligten werden bis 2030 ausgesetzt.",
    "text": "تخلیه اجباری افراد کم‌بضاعت تا سال ۲۰۳۰ به تعویق می‌افتد"
  },
  {
    "id": 12,
    "source": "Mietverträge automatisch verlängert.",
    "text": "قراردادهای اجاره به‌طور خودکار تمدید می‌شوند"
  },
  {
    "id": 13,
    "source": "Die Vermietung von Ferienwohnungen strenger geregelt.",
    "text": "اجاره خانه‌های تعطیلاتی با مقررات سخت‌گیرانه‌تری کنترل می‌شود"
  },
  {
    "id": 14,
    "source": "Und auch Immobilienfonds stehen zunehmend im Fokus der Behörden.",
    "text": "و صندوق‌های املاک و مستغلات نیز بیش از پیش مورد توجه مقامات قرار گرفته‌اند"
  },
  {
    "id": 15,
    "source": "nombres y apellidos a los especuladores,",
    "text": "نام و نام خانوادگی سوداگران را مشخص می‌کنیم"
  },
  {
    "id": 16,
    "source": "sino que además vamos a identificar a esas empresas para prohibirles que sigan mercadeando con un bien esencial,",
    "text": "و علاوه بر آن، این شرکت‌ها را شناسایی می‌کنیم تا از تجارت آن‌ها با یک کالای اساسی جلوگیری کنیم"
  },
  {
    "id": 17,
    "source": "de manera que vamos a paralizar esta compra por parte de los fondos buitres",
    "text": "به طوری که ما این خرید توسط صندوق‌های کرکس را متوقف خواهیم کرد"
  },
  {
    "id": 18,
    "source": "para parar la compra especulativa.",
    "text": "تا جلوی خرید سوداگرانه گرفته شود"
  },
  {
    "id": 19,
    "source": "Ein Stopp, der bis 2028 gelten sollte.",
    "text": "توقفی که قرار بود تا سال ۲۰۲۸ معتبر باشد"
  },
  {
    "id": 20,
    "source": "Aber die Pläne wurden am 2. Oktober vom Parlament abgelehnt.",
    "text": "اما این طرح‌ها در ۲ اکتبر توسط پارلمان رد شدند"
  },
  {
    "id": 21,
    "source": "Ministerpräsident Pedro Sánchez hat daraufhin vorgezogene Neuwahlen angekündigt und hofft jetzt auf eine Mehrheit in\neiner Art Notparlament.",
    "text": "نخست‌وزیر پدرو سانچز در پی آن انتخابات زودهنگام اعلام کرد و اکنون به کسب اکثریت در\nنوعی پارلمان اضطراری امیدوار است"
  },
  {
    "id": 22,
    "source": "einer Art Notparlament.",
    "text": "نوعی پارلمان اضطراری"
  },
  {
    "id": 23,
    "source": "Die Mieter-Vereinigung von Madrid hat die Sánchez-Maßnahmen jedenfalls begrüßt.",
    "text": "به هر حال، انجمن مستاجران مادرید از اقدامات سانچز استقبال کرده است"
  },
  {
    "id": 24,
    "source": "Aber er geht ihr nicht weit genug.",
    "text": "اما این اقدامات برای آن‌ها کافی نیست"
  },
  {
    "id": 25,
    "source": "La solución de la expropiación la hemos propuesto muchas veces y en concreto con la vivienda pública.",
    "text": "ما بارها راه حل مصادره را پیشنهاد داده‌ایم، به‌ویژه در مورد مسکن عمومی"
  }
]

[
  {
    "id": 1,
    "source": "Und die Wohnungsnot wird größer.",
    "text": "و کمبود مسکن رو به افزایش است"
  },
  {
    "id": 2,
    "source": "Also, Bauen für Wohnungskonzerne simpler und billiger machen,",
    "text": "بنابراین، ساده‌تر و ارزان‌تر کردن ساخت‌وساز برای شرکت‌های مسکن،"
  },
  {
    "id": 3,
    "source": "sie stärker in die Verantwortung nehmen und besteuern oder sie sogar enteignen.",
    "text": "پاسخگوتر کردن آن‌ها، دریافت مالیات یا حتی مصادره اموالشان"
  },
  {
    "id": 4,
    "source": "Ihre Rolle rückt auf jeden Fall gerade in den Fokus.",
    "text": "در هر صورت، نقش آن‌ها اکنون در کانون توجه قرار گرفته است"
  },
  {
    "id": 5,
    "source": "Und das ist natürlich eine hochpolitische Debatte.",
    "text": "و این طبیعتاً یک بحث بسیار سیاسی است"
  },
  {
    "id": 6,
    "source": "Da clasht staatliche Regulierung mit freier Marktwirtschaft, Gemeinwohl mit dem Schutz von Privateigentum.",
    "text": "در اینجا مقررات دولتی با اقتصاد بازار آزاد و منافع عمومی با حفاظت از مالکیت خصوصی در تضاد هستند"
  },
  {
    "id": 7,
    "source": "Und welchen Weg Berlin und Spanien jetzt einschlagen,",
    "text": "و مسیری که برلین و اسپانیا اکنون در پیش می‌گیرند،"
  },
  {
    "id": 8,
    "source": "das werden andere Großstädte und Länder mit ähnlichen Problemen natürlich genau beobachten.",
    "text": "قطعاً توسط سایر کلان‌شهرها و کشورهایی که مشکلات مشابهی دارند، به دقت زیر نظر گرفته خواهد شد"
  },
  {
    "id": 9,
    "source": "Und ihr? Welche Lösungen wünscht ihr euch für die Wohnungskrise?",
    "text": "و شما چطور؟ چه راهکارهایی برای بحران مسکن پیشنهاد می‌کنید؟"
  },
  {
    "id": 10,
    "source": "Ich sage Tschüss für heute, bis zum nächsten Mal.",
    "text": "برای امروز خداحافظی می‌کنم، تا برنامه بعد"
  }
]
